// Silences Kotlin/Java compiler warnings from third-party native modules
// (expo, expo-modules-core, expo-dev-menu, ...). Those warnings are deprecation
// notices inside node_modules that only upstream releases can fix. The :app
// module keeps its warnings. android/ is generated by prebuild, so this has to
// live in a config plugin rather than in android/build.gradle.
const {
  withGradleProperties,
  withProjectBuildGradle,
} = require("expo/config-plugins");

const MARKER = "// @generated withQuietLibraryWarnings";

const SNIPPET = `
${MARKER}
subprojects { subproject ->
  if (subproject.name == "app") return
  subproject.tasks.withType(org.jetbrains.kotlin.gradle.tasks.KotlinCompile).configureEach {
    compilerOptions.suppressWarnings.set(true)
  }
  subproject.tasks.withType(JavaCompile).configureEach {
    options.compilerArgs += ["-nowarn", "-Xlint:none", "-XDsuppressNotes"]
  }
}
// expo-dev-launcher's GraphQL queries use fields Expo's API has deprecated.
gradle.projectsEvaluated {
  subprojects { subproject ->
    subproject.tasks.configureEach { task ->
      if (task.class.name.startsWith("com.apollographql.apollo.gradle.internal.ApolloGenerateOptionsTask")) {
        task.warnOnDeprecatedUsages.set(false)
      }
    }
  }
}
`;

// The default 512m metaspace runs out on a full release build, which logs a
// warning and kills the Gradle daemon at the end of every build.
const JVM_ARGS = "-Xmx4096m -XX:MaxMetaspaceSize=1024m";

module.exports = function withQuietLibraryWarnings(config) {
  config = withProjectBuildGradle(config, (cfg) => {
    if (!cfg.modResults.contents.includes(MARKER)) {
      cfg.modResults.contents += SNIPPET;
    }
    return cfg;
  });
  return withGradleProperties(config, (cfg) => {
    const item = cfg.modResults.find(
      (p) => p.type === "property" && p.key === "org.gradle.jvmargs",
    );
    if (item) {
      item.value = JVM_ARGS;
    } else {
      cfg.modResults.push({ type: "property", key: "org.gradle.jvmargs", value: JVM_ARGS });
    }
    return cfg;
  });
};
